package com.fromscratch.wealth;

import com.fromscratch.bank.*;
import com.fromscratch.SnapshotFixtures;
import com.fromscratch.model.ContainerSnapshot;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class WealthModelTest
{
	private static final int ITEM=ItemID.WOODEN_SHIELD,OTHER=ItemID.LOGS;
	private final UUID session=UUID.randomUUID();
	private final Instant at=SnapshotFixtures.TIME;
	private ContainerSnapshot bank(long quantity){return new ContainerSnapshot(quantity==0?Collections.emptyMap():Collections.singletonMap(ITEM,quantity),quantity==0?0:1);}
	private BankRun start(long n){return BankEngine.start(SnapshotFixtures.CHARACTER_A,null,bank(n),true,session,at);}
	private Map<Integer,PriceQuote> quote(long n){return Collections.singletonMap(ITEM,new PriceQuote(ITEM,n,at,PriceQuote.Source.RUNELITE_GE_GUIDE,false));}
	private BankRun observe(BankRun before,long n,long price){return BankEngine.observe(before,bank(n),session,at,null,quote(price));}
	@Test public void positiveBankProgressHasMarketValue(){BankRun run=observe(start(0),2,100);assertEquals(Long.valueOf(200),BankValuation.calculate(run,quote(100)).getSubtotalGp());}
	@Test public void negativeBankProgressHasNegativeMarketValue(){BankRun run=observe(start(2),1,100);assertEquals(Long.valueOf(-100),BankValuation.calculate(run,quote(100)).getSubtotalGp());}
	@Test public void zeroLegacyProgressHasNoValue(){assertEquals(Long.valueOf(0),BankValuation.calculate(start(100),quote(900)).getSubtotalGp());}
	@Test public void unknownIsNotAZeroPrice(){BankRun run=observe(start(0),1,100);BankValuation result=BankValuation.calculate(run,Collections.emptyMap());assertEquals(1,result.getMissingTypes());assertEquals("Unavailable",result.label());assertTrue(result.explanation().contains("No verified current price records"));}
	@Test public void verifiedZeroIsNotMissing(){BankRun run=observe(start(0),1,0);assertEquals(0,BankValuation.calculate(run,quote(0)).getMissingTypes());assertTrue(run.getFinancial().getUnpricedGains().isEmpty());}
	@Test public void staleCurrentQuoteIsRetainedAndMarked(){BankRun run=observe(start(0),1,100);PriceQuote stale=new PriceQuote(ITEM,90L,at,PriceQuote.Source.RUNELITE_GE_GUIDE,true);BankValuation v=BankValuation.calculate(run,Collections.singletonMap(ITEM,stale));assertEquals(Long.valueOf(90),v.getSubtotalGp());assertEquals(1,v.getStaleTypes());}
	@Test public void gainsOnlyRecognizeProgressAboveHighWater(){BankRun run=observe(start(100),102,10);assertEquals(20,run.getFinancial().getGainedGp());run=observe(run,103,20);assertEquals(40,run.getFinancial().getGainedGp());}
	@Test public void withdrawalAndRedepositDoNotRepeatGain(){BankRun run=observe(start(0),2,100);run=observe(run,1,200);run=observe(run,2,300);assertEquals(200,run.getFinancial().getGainedGp());assertEquals(1,run.getFinancial().getEventCount());}
	@Test public void legacyWithdrawalAndReturnDoNotEarn(){BankRun run=observe(start(100),99,10);run=observe(run,100,100);assertEquals(0,run.getFinancial().getGainedGp());assertEquals(0,run.getFinancial().getEventCount());}
	@Test public void historicalPriceStaysFixedAsCurrentPriceChanges(){BankRun run=observe(start(0),2,100);assertEquals(Long.valueOf(1800),BankValuation.calculate(run,quote(900)).getSubtotalGp());assertEquals(200,run.getFinancial().getGainedGp());assertEquals(Long.valueOf(100),run.getRecent().get(0).getValuations().get(0).getQuote().getUnitGp());}
	@Test public void unknownHistoricalGainNeverBackfillsWithNewerPrice(){BankRun run=BankEngine.observe(start(0),bank(2),session,at);assertEquals(Long.valueOf(2),run.getFinancial().getUnpricedGains().get(ITEM));run=observe(run,1,100);run=observe(run,2,100);assertEquals(0,run.getFinancial().getGainedGp());}
	@Test public void staleHistoricalQuoteIsUnpricedEvidence(){BankRun run=BankEngine.observe(start(0),bank(1),session,at,null,Collections.singletonMap(ITEM,new PriceQuote(ITEM,100L,at,PriceQuote.Source.RUNELITE_GE_GUIDE,true)));assertEquals(0,run.getFinancial().getGainedGp());assertEquals(Long.valueOf(1),run.getFinancial().getUnpricedGains().get(ITEM));assertTrue(run.getRecent().get(0).getValuations().get(0).getQuote().isStale());}
	@Test public void upwardCorrectionDoesNotEarnAndRaisesCeiling(){BankRun run=BankEngine.correct(start(10),ITEM,5,session,at);assertEquals(0,run.getFinancial().getGainedGp());run=observe(run,9,100);run=observe(run,10,100);assertEquals(0,run.getFinancial().getGainedGp());run=observe(run,11,100);assertEquals(100,run.getFinancial().getGainedGp());}
	@Test public void downwardCorrectionDoesNotLowerCeiling(){BankRun run=observe(start(0),2,100);run=BankEngine.correct(run,ITEM,0,session,at);run=observe(run,4,100);assertEquals(200,run.getFinancial().getGainedGp());assertEquals(Long.valueOf(2),run.getFinancial().getHighWater().get(ITEM));}
	@Test public void ordinaryWithdrawalIsNotAnExpense(){BankRun run=observe(observe(start(0),2,100),1,100);assertEquals(0,run.getFinancial().getExpenseRecords());assertEquals(0,run.getFinancial().getExpenseGp());}
	@Test public void explicitExpenseDoesNotDeductBankOrCoins(){BankRun before=observe(start(0),2,100);BankRun after=BankEngine.expense(before,300,"Verified reclaim fee",session,at);assertEquals(before.getBalances(),after.getBalances());assertEquals(before.getPhysical(),after.getPhysical());assertEquals(300,after.getFinancial().getExpenseGp());assertEquals(1,after.getFinancial().getExpenseRecords());assertEquals(ValuationEvent.Kind.EXPENSE,after.getRecent().get(0).getValuations().get(0).getKind());}
	@Test(expected=IllegalArgumentException.class) public void zeroExpenseIsRejected(){BankEngine.expense(start(0),0,"Fee",session,at);}
	@Test(expected=IllegalArgumentException.class) public void unexplainedExpenseIsRejected(){BankEngine.expense(start(0),100," ",session,at);}
	@Test(expected=ArithmeticException.class) public void historicalGainOverflowRejectsWholeOperation(){observe(start(0),Long.MAX_VALUE,2);}
	@Test public void currentOverflowIsUnavailableRatherThanWrapped(){BankRun run=observe(start(0),Long.MAX_VALUE,0);assertNull(BankValuation.calculate(run,quote(2)).getSubtotalGp());}
	@Test public void distinctVariantsDoNotShareHighWater(){Map<Integer,Long> quantities=new TreeMap<>();quantities.put(ITEM,1L);quantities.put(OTHER,2L);BankRun run=BankEngine.observe(start(0),new ContainerSnapshot(quantities,2),session,at);assertEquals(Long.valueOf(1),run.getFinancial().getHighWater().get(ITEM));assertEquals(Long.valueOf(2),run.getFinancial().getHighWater().get(OTHER));}
	@Test public void coinsHaveOneExactGpContributionIncludingNegative(){for(long n:new long[]{50_000,-100_000}){BankRun run=BankEngine.start(SnapshotFixtures.CHARACTER_A,null,new ContainerSnapshot(Collections.singletonMap(ItemID.COINS,1_000_000L),1),true,session,at);run=BankEngine.observe(run,new ContainerSnapshot(Collections.singletonMap(ItemID.COINS,1_000_000L+n),1),session,at);assertEquals(n,run.balance(ItemID.COINS));assertEquals(Long.valueOf(n),BankValuation.calculate(run,Collections.singletonMap(ItemID.COINS,new PriceQuote(ItemID.COINS,99L,at,PriceQuote.Source.RUNELITE_GE_GUIDE,false))).getSubtotalGp());assertEquals(Math.max(n,0),run.getFinancial().getGainedGp());}}
	@Test public void pricesAreCachedAcrossManySnapshots(){AtomicInteger fetches=new AtomicInteger();PriceService service=new PriceService(()->{fetches.incrementAndGet();return Collections.singletonMap(ITEM,100L);},()->at);service.register(Collections.singleton(ITEM),id->id);service.refresh();for(int i=0;i<100;i++){assertEquals(Long.valueOf(100),service.snapshot(Collections.singleton(ITEM)).get(ITEM).getUnitGp());}assertEquals(1,fetches.get());}
	@Test public void cacheDistinguishesMissingAndActualZeroRecords(){PriceService service=new PriceService(()->Collections.singletonMap(ITEM,0L),()->at);service.register(Arrays.asList(ITEM,OTHER),id->id);service.refresh();Map<Integer,PriceQuote> quotes=service.snapshot(Arrays.asList(ITEM,OTHER));assertTrue(quotes.get(ITEM).verifiedNow());assertNull(quotes.get(OTHER).getUnitGp());}
	@Test public void notedIdentityNormalizesPriceWithoutMergingVariants(){AtomicInteger definitions=new AtomicInteger();PriceService service=new PriceService(()->Collections.singletonMap(ITEM,100L),()->at);service.register(Arrays.asList(ITEM,OTHER),id->{definitions.incrementAndGet();return id==OTHER?ITEM:id;});service.register(Arrays.asList(ITEM,OTHER),id->{fail("Cached definitions must not be reread");return id;});service.refresh();assertEquals(2,definitions.get());assertEquals(ITEM,service.snapshot(Collections.singleton(OTHER)).get(OTHER).getPriceId());}
	@Test public void failedRefreshPreservesLastVerifiedValueAsStale(){AtomicBoolean fail=new AtomicBoolean();PriceService service=new PriceService(()->{if(fail.get()){throw new java.io.IOException("Unavailable");}return Collections.singletonMap(ITEM,100L);},()->at);service.register(Collections.singleton(ITEM),id->id);service.refresh();fail.set(true);service.refresh();PriceQuote quote=service.snapshot(Collections.singleton(ITEM)).get(ITEM);assertEquals(Long.valueOf(100),quote.getUnitGp());assertTrue(quote.isStale());assertEquals(at,quote.getReceivedAt());}
	@Test public void cacheExpiresWithoutInventingFreshness(){AtomicReference<Instant> clock=new AtomicReference<>(at);PriceService service=new PriceService(()->Collections.singletonMap(ITEM,100L),clock::get);service.register(Collections.singleton(ITEM),id->id);service.refresh();clock.set(at.plusSeconds(1800));assertTrue(service.snapshot(Collections.singleton(ITEM)).get(ITEM).isStale());}
	@Test public void noPriceLookupFetchesDuringSnapshotOrRegistration(){PriceService service=new PriceService(()->{fail("No network from a snapshot");return null;},()->at);service.register(Collections.singleton(ITEM),id->id);assertNull(service.snapshot(Collections.singleton(ITEM)).get(ITEM).getUnitGp());}
	@Test public void monetaryFormatterUsesIntegerCompactLabelsAndExactGroupedDetails(){assertEquals("1740K GP",GpFormatter.compact(1_740_000));assertEquals("-1740K GP",GpFormatter.compact(-1_740_000));assertEquals("1,740,000 GP",GpFormatter.exact(1_740_000));assertFalse(GpFormatter.compact(Long.MIN_VALUE).contains("--"));}
	@Test public void duplicateFinancialEventEvidenceIsRejected(){BankRun run=observe(start(0),1,100);BankAudit audit=run.getRecent().get(0);BankAudit duplicate=new BankAudit(audit.getId(),session,at,audit.getKind(),audit.getPhysicalChanges(),audit.getBalanceChanges(),audit.getReason(),Arrays.asList(audit.getValuations().get(0),audit.getValuations().get(0)));try{FinancialEngine.advance(start(0).getFinancial(),run.getBalances(),duplicate);fail();}catch(IllegalArgumentException expected){}}
	@Test public void offsettingLargeContributionsAreIndependentOfIterationOrder(){Map<Integer,Long> balances=new TreeMap<>(),physical=new TreeMap<>();balances.put(ITEM,Long.MAX_VALUE);balances.put(OTHER,-Long.MAX_VALUE);physical.put(ITEM,Long.MAX_VALUE);BankRun initial=start(0);BankRun run=new BankRun(initial.getCharacter(),initial.getRunId(),null,at,initial.getRevision(),1,initial.getInitialBank(),physical,balances,true,null,null,initial.getRecent(),null);Map<Integer,PriceQuote> prices=new HashMap<>();prices.put(ITEM,new PriceQuote(ITEM,2L,at,PriceQuote.Source.RUNELITE_GE_GUIDE,false));prices.put(OTHER,new PriceQuote(OTHER,2L,at,PriceQuote.Source.RUNELITE_GE_GUIDE,false));assertEquals(Long.valueOf(0),BankValuation.calculate(run,prices).getSubtotalGp());}
}
